"""Genuine Zstd journals generated by authorised native Splunk ingestion."""
import csv
import hashlib
import json
from pathlib import Path
import re

import pytest

from obs_migrate.dataset import export_dataset
from obs_migrate.export import export, read_export
from obs_migrate.journal import events
from obs_migrate.oracle import decode_envelope, fraction
from obs_migrate.oracle import actual_signature, expected_signature

ROOT = Path(__file__).parent/'fixtures/current-producer-10.6.0.5'
PROVENANCE = json.loads((ROOT/'provenance.json').read_text())


def test_original_native_producer_fixture_hashes_and_compression():
    assert PROVENANCE['producer']['VERSION'] == '10.6.0.5'
    assert PROVENANCE['producer']['BUILD'] == '86587d4e3b27'
    assert PROVENANCE['input_events'] == 8
    assert PROVENANCE['binary_origin'] == 'native Splunk ingestion and hot-to-warm roll; no fabricated proprietary bytes'
    for name,digest in PROVENANCE['fixture_files'].items():
        assert hashlib.sha256((ROOT/name).read_bytes()).hexdigest() == digest
    for bucket in PROVENANCE['buckets']:
        assert (ROOT/bucket/'rawdata/journal.zst').read_bytes()[:4] == b'\x28\xb5\x2f\xfd'


@pytest.mark.parametrize('bucket', list(PROVENANCE['buckets']))
@pytest.mark.parametrize('format', ['ndjson','parquet','parquet-dataset'])
@pytest.mark.parametrize('visibility', ['physical','undeleted'])
def test_real_zstd_producer_matches_native_offline_oracle(tmp_path,bucket,format,visibility):
    with (ROOT/(bucket+'.csv')).open(newline='') as file:
        expected = list(csv.DictReader(file))
    source = events(ROOT/bucket, experimental=True, visibility=visibility)
    out = tmp_path/format
    if format == 'parquet-dataset':
        export_dataset(source,out,partition_rows=2)
    else:
        export(source,out,format)
    actual = list(read_export(out,format))
    assert len(actual) == len(expected)
    for native,row in zip(expected,actual):
        assert row['raw'] == native['_raw'].encode('utf8')
        for key in ('host','source','sourcetype'):
            assert row[key] == native[key].encode('utf8')
        subsecond = re.search(r'(?:^| )_subsecond::([^ ]+)',native['_meta'])
        index = re.search(r'(?:^| )_indextime::([0-9]+)',native['_meta'])
        assert row['event_time'] == {'seconds':int(native['_time']),
                                     'fraction':fraction(subsecond.group(1)) if subsecond else '0'}
        assert row['index_time'] == {'seconds':int(index.group(1)),'fraction':'0'}


def test_native_ingestion_transformations_and_duplicate_multiplicity():
    rows = [r for bucket in PROVENANCE['buckets'] for r in events(ROOT/bucket,experimental=True)]
    assert len(rows) == 8
    duplicate = [r for r in rows if b'legitimate duplicate' in r['raw']]
    assert len(duplicate) == 2
    assert duplicate[0]['record_ordinal'] != duplicate[1]['record_ordinal']
    assert duplicate[0]['raw'] == duplicate[1]['raw']
    next_second = next(r for r in rows if b'signed32 next second' in r['raw'])
    assert b'2038-01-19T03:14:08.987654321Z' in next_second['raw']
    assert next_second['event_time'] == {'seconds':2147483647,'fraction':'0.987654'}
    # These are observed native ingestion results, never repaired from raw text.
    nine = next(r for r in rows if b'case=nine digits' in r['raw'])
    assert nine['event_time']['fraction'] == '0.123456'
    native_search = [decode_envelope(line)['result'] for line in (ROOT/'events.jsonl').read_bytes().splitlines()]
    assert len(native_search) == 8
    by_locator = {}
    for bucket in PROVENANCE['buckets']:
        bid = bucket.rsplit('_',1)[1]
        for row in events(ROOT/bucket,experimental=True):
            by_locator[f'{bid}:{row["decompressed_offset"] >> 5}'] = row
    for native in native_search:
        assert actual_signature(native) == expected_signature(by_locator[native['_cd']])
    assert any('café 🧪'.encode() in r['raw'] for r in rows)
